n    \"@types/node\": \"24.12.4\",\n    \"typescript\": \"5.9.3\",\n    \"vitest\": \"4.1.9\",\n    \"zod\": \"4.4.3\",\n    \"rolldown\": \"1.2.4\"\n  }\n}\n"
